<?php
namespace App\Http\Controllers;use App\Models\FeedbackResponse;use App\Services\FeedbackCorrelationService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class FeedbackAdminController extends Controller{public function index(Request $r):View{abort_unless($r->user()->can('dashboard.view'),403);$feedback=FeedbackResponse::with(['building','floor','surveyArea','correlations'])->latest('submitted_at')->paginate(30);$stats=['count'=>FeedbackResponse::count(),'average_satisfaction'=>round((float)FeedbackResponse::avg('overall_satisfaction'),2),'common_problems'=>FeedbackResponse::selectRaw('problem_type,count(*) as total')->groupBy('problem_type')->orderByDesc('total')->limit(5)->get()];return view('feedback.index',compact('feedback','stats'));}public function correlate(Request $r,FeedbackResponse $feedbackResponse,FeedbackCorrelationService $service):JsonResponse{abort_unless($r->user()->can('insights.review'),403);return response()->json($service->correlate($feedbackResponse));}}
